import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = data[2:2+n]

    n1 = n // 2
    n2 = n - n1
    left = a[:n1]
    right = a[n1:]

    left_sums = []
    for mask in range(1 << n1):
        s = 0
        for i in range(n1):
            if mask & (1 << i):
                s += left[i]
        left_sums.append(s % m)

    right_sums = []
    for mask in range(1 << n2):
        s = 0
        for i in range(n2):
            if mask & (1 << i):
                s += right[i]
        right_sums.append(s % m)

    left_sums.sort()
    right_sums.sort()

    ans = 0
    j = len(right_sums) - 1
    for x in left_sums:
        while j >= 0 and x + right_sums[j] >= m:
            j -= 1
        if j >= 0:
            ans = max(ans, x + right_sums[j])
        else:
            break

    print(ans)

if __name__ == "__main__":
    main()
